/* Filamentos 3D v2.0 Beta — PWA offline-first con interfaz ES/DE/EN */
const DB_NAME='filamentos3d-db', DB_VERSION=1, STORE='app';
const PRESET_COLORS=['#FFFFFF','#111111','#888888','#E53935','#1565C0','#2E7D32','#FDD835','#EF6C00','#7B1FA2','#795548','#00BCD4','#F06292','#B0BEC5','#D4AF37','#B5E5F2'];
const COLOR_LABELS={'#FFFFFF':'Blanco','#111111':'Negro','#888888':'Gris','#E53935':'Rojo','#1565C0':'Azul','#2E7D32':'Verde','#FDD835':'Amarillo','#EF6C00':'Naranja','#7B1FA2':'Violeta','#795548':'Marrón','#00BCD4':'Cian','#F06292':'Rosa','#B0BEC5':'Plateado','#D4AF37':'Dorado','#B5E5F2':'Transparente'};
const $=id=>document.getElementById(id);
const state={filaments:[],columns:5,hideEmpty:false,view:'list',palette:[],catalogs:{brands:[],materials:[],names:[],colors:[]},templates:[],suppliers:[]};
let currentPhoto=null,currentDetailId=null,currentManagerKind=null;
let db, toastTimer, editingRolls=[], reelSequence=0, currentDbKey='main';

function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains(STORE))d.createObjectStore(STORE,{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function loadState(key=currentDbKey){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readonly'),r=tx.objectStore(STORE).get(key);r.onsuccess=()=>resolve(r.result?.value||null);r.onerror=()=>reject(r.error);});}
function serializeState(){return{filaments:state.filaments,columns:state.columns,hideEmpty:state.hideEmpty,view:state.view,palette:state.palette,catalogs:state.catalogs,templates:state.templates,suppliers:state.suppliers};}
function saveState(){return new Promise((resolve,reject)=>{const value=serializeState(),tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put({id:currentDbKey,value});tx.oncomplete=async()=>{try{await window.FilamentCloud?.localSaved({filaments:value.filaments,palette:value.palette,catalogs:value.catalogs,templates:value.templates,suppliers:value.suppliers},currentDbKey);resolve();}catch(e){console.warn('Cloud status save:',e);void window.FilamentDiagnostics?.log('Estado de nube local',e);resolve();}};tx.onerror=()=>reject(tx.error);});}
function applyPayload(p){state.filaments=mergeDuplicateFilaments(p?.filaments||[]);state.palette=Array.isArray(p?.palette)?p.palette:[];state.catalogs=p?.catalogs||{brands:[],materials:[],names:[],colors:[]};state.templates=Array.isArray(p?.templates)?p.templates:[];state.suppliers=Array.isArray(p?.suppliers)?p.suppliers:[];if(p&&Number.isFinite(Number(p.columns)))state.columns=Math.max(2,Math.min(15,Number(p.columns)));if(p&&Object.hasOwn(p,'hideEmpty'))state.hideEmpty=!!p.hideEmpty;if(p&&Object.hasOwn(p,'view'))state.view=['list','grid'].includes(p.view)?p.view:'list';}
async function switchProfile(uid){currentDbKey=uid?'profile:'+uid:'main';const stored=await loadState(currentDbKey);applyPayload(stored||{});if(!stored){await new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put({id:currentDbKey,value:serializeState()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}render();}
window.FilamentApp={getPayload:()=>({filaments:state.filaments,palette:state.palette,catalogs:state.catalogs,templates:state.templates,suppliers:state.suppliers}),replacePayload:async p=>{applyPayload(p);await saveState();render();},switchProfile,getProfileKey:()=>currentDbKey,isEditing:()=>['filamentDialog','bulkAddDialog','managerDialog'].some(id=>$(id)?.open)};
const uid=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const n=v=>Number.isFinite(Number(v))?Number(v):0;
const locale=()=>window.FilamentI18n?.locale()||'es-ES';
const fmtNumber=(v,d=0)=>new Intl.NumberFormat(locale(),{minimumFractionDigits:d,maximumFractionDigits:d}).format(n(v));
const grams=v=>`${fmtNumber(Math.round(n(v)))} g`;
const euro=v=>new Intl.NumberFormat(locale(),{style:'currency',currency:'EUR'}).format(n(v));
const pct=(remaining,initial)=>initial>0?Math.max(0,Math.min(100,remaining/initial*100)):0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function norm(v){return String(v||'').trim().replace(/\s+/g,' ').toLocaleLowerCase('es');}
function productKey(f){return [norm(f.brand),norm(f.name),norm(f.material),String(f.colorHex||'#3478d4').toLowerCase(),norm(f.finish||'normal'),norm(f.customFinishName),norm(f.customFinishEffect),f.nozzleMin??'',f.nozzleMax??'',f.bedMin??'',f.bedMax??''].join('|');}
function mergeDuplicateFilaments(list){const by=new Map(),merged=[];for(const raw of list||[]){const f={...raw,rolls:Array.isArray(raw.rolls)?raw.rolls:[]};f.rolls=f.rolls.map(r=>({...r,id:r.id||uid(),initialG:n(r.initialG),remainingG:n(r.remainingG),price:n(r.price),supplier:r.supplier||'',supplierUrl:r.supplierUrl||''}));const key=productKey(f),existing=by.get(key);if(existing){const known=new Set(existing.rolls.map(r=>r.id));for(const r of f.rolls){if(known.has(r.id))r.id=uid();existing.rolls.push(r);}if(!existing.imageData&&f.imageData)existing.imageData=f.imageData;}else{by.set(key,f);merged.push(f);}}return merged;}
function totals(f){const rolls=f.rolls||[],initial=rolls.reduce((a,r)=>a+n(r.initialG),0),remaining=rolls.reduce((a,r)=>a+n(r.remainingG),0),spent=initial-remaining,invested=rolls.reduce((a,r)=>a+n(r.price),0),remainingValue=rolls.reduce((a,r)=>a+(n(r.initialG)>0?n(r.price)*n(r.remainingG)/n(r.initialG):0),0);return{rolls:rolls.length,available:rolls.filter(r=>n(r.remainingG)>0).length,empty:rolls.filter(r=>n(r.remainingG)<=0).length,initial,remaining,spent,invested,remainingValue,percent:pct(remaining,initial)}}
function reel(color='#555555',empty=false,cls='reel',count=1,finish='normal'){
 const c=/^#[0-9a-f]{6}$/i.test(color)?color:'#555555',id=`coil${++reelSequence}`;
 const fs=count>=100?14:count>=10?19:27;
 const stops=finish==='metallic'?`<linearGradient id="${id}fil" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#343a44"/><stop offset=".18" stop-color="${c}"/><stop offset=".30" stop-color="#fff"/><stop offset=".39" stop-color="#7d8793"/><stop offset=".52" stop-color="#f8fbff"/><stop offset=".63" stop-color="${c}"/><stop offset=".81" stop-color="#fff"/><stop offset="1" stop-color="#343a44"/></linearGradient>`:
 finish==='glossy'?`<linearGradient id="${id}fil" x1=".05" y1="0" x2=".8" y2="1"><stop stop-color="#fff"/><stop offset=".17" stop-color="${c}"/><stop offset=".40" stop-color="#fff" stop-opacity=".18"/><stop offset=".70" stop-color="${c}"/><stop offset=".88" stop-color="#fff" stop-opacity=".82"/><stop offset="1" stop-color="${c}"/></linearGradient>`:
 finish==='transparent'?`<linearGradient id="${id}fil" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff" stop-opacity=".9"/><stop offset=".18" stop-color="${c}" stop-opacity=".52"/><stop offset=".52" stop-color="${c}" stop-opacity=".32"/><stop offset=".78" stop-color="#efffff" stop-opacity=".62"/><stop offset="1" stop-color="${c}" stop-opacity=".55"/></linearGradient>`:
 `<radialGradient id="${id}fil" cx="32%" cy="25%" r="82%"><stop stop-color="#fff" stop-opacity=".42"/><stop offset=".28" stop-color="${c}"/><stop offset=".78" stop-color="${c}"/><stop offset="1" stop-color="#080a0d" stop-opacity=".72"/></radialGradient>`;
 let coils='';
 for(let i=0;i<7;i++){const r=34+i*2.15;coils+=`<circle cx="60" cy="60" r="${r}" fill="none" stroke="#05070a" stroke-width="3.1" opacity=".68"/><circle cx="60" cy="60" r="${r}" fill="none" stroke="url(#${id}fil)" stroke-width="2.5"/><circle cx="60" cy="60" r="${r-.6}" fill="none" stroke="#fff" stroke-width=".55" stroke-dasharray="34 320" stroke-dashoffset="-${i*7}" opacity="${finish==='matte'?'.16':'.42'}"/>`;}
 let effect='';
 if(finish==='metallic')effect=`<path d="M19 44 A45 45 0 0 1 50 15" fill="none" stroke="#fff" stroke-width="3.2" stroke-linecap="round"/><path d="M74 17 A45 45 0 0 1 101 44" fill="none" stroke="#f4f7ff" stroke-width="2"/>`;
 if(finish==='glossy')effect=`<path d="M18 43 C25 23 43 13 58 14" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round"/><path d="M24 47 C30 31 41 23 53 21" fill="none" stroke="#fff" stroke-width="1.8"/><path d="M79 17 A42 42 0 0 1 101 44" fill="none" stroke="#fff" stroke-width="2.5"/>`;
 if(finish==='transparent')effect=`<circle cx="60" cy="60" r="42" fill="none" stroke="#eaffff" stroke-width="1.7" opacity=".94"/><path d="M18 47 A43 43 0 0 1 48 15" fill="none" stroke="#fff" stroke-width="3.7" stroke-linecap="round"/><path d="M100 46 A42 42 0 0 1 89 81" fill="none" stroke="#d8ffff" stroke-width="2.4"/>`;
 if(finish==='matte')effect=`<circle cx="60" cy="60" r="41" fill="none" stroke="#fff" stroke-width="12" stroke-dasharray="1 3" opacity=".16"/>`;
 if(finish==='multicolor'){const colors=['#f52832','#ff9d1e','#ffe947','#4bdd5a','#10d9c7','#258bff','#704bff','#dc47d5'];effect=colors.map((x,i)=>`<circle cx="60" cy="60" r="42" fill="none" stroke="${x}" stroke-width="7.5" stroke-dasharray="24 240" stroke-dashoffset="-${i*33}"/>`).join('')+`<circle cx="60" cy="60" r="42" fill="none" stroke="#fff" stroke-width="1.3" stroke-dasharray="44 220" opacity=".8"/>`;}
 const bolts=[0,45,90,135,180,225,270,315].map(a=>`<g transform="rotate(${a} 60 60)"><circle cx="60" cy="7" r="1.7" fill="#090c10" stroke="#87909b" stroke-width=".6"/></g>`).join('');
 return `<svg class="${cls}" viewBox="0 0 120 120" role="img" aria-label="Bobina, ${count} rollos, acabado ${esc(finish)}"><defs>${stops}<radialGradient id="${id}rim" cx="35%" cy="25%"><stop stop-color="#59616c"/><stop offset=".5" stop-color="#202630"/><stop offset="1" stop-color="#080b10"/></radialGradient></defs><circle cx="60" cy="60" r="56" fill="url(#${id}rim)" stroke="#98a1ad" stroke-width="1.3"/><circle cx="60" cy="60" r="52" fill="none" stroke="#080a0d" stroke-width="2.5"/><circle cx="60" cy="60" r="49" fill="none" stroke="#8c95a0" stroke-width=".7" opacity=".75"/>${bolts}<circle cx="60" cy="60" r="47" fill="none" stroke="#07090d" stroke-width="2"/>${coils}${effect}<circle cx="60" cy="60" r="29" fill="url(#${id}rim)" stroke="#adb5c0" stroke-width="1.4"/><circle cx="60" cy="60" r="23" fill="#11161d" stroke="#66707d" stroke-width="1.8"/><circle cx="60" cy="60" r="20" fill="#191f28" stroke="#aab3be" stroke-width="1.1"/><text x="60" y="60" text-anchor="middle" dominant-baseline="central" fill="#fff" font-family="system-ui,sans-serif" font-weight="800" font-size="${fs}" stroke="#11161d" stroke-width=".8" paint-order="stroke">${Math.max(1,Number(count)||1)}</text>${empty?'<path d="M20 20L100 100M100 20L20 100" stroke="#e33238" stroke-width="9" stroke-linecap="round"/>':''}</svg>`;
}
function showToast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600);}
function emptyState(title,body,button=''){return `<div class="empty-state"><div class="empty-icon">◉</div><h3>${esc(title)}</h3><p>${esc(body)}</p>${button?`<button class="primary-button" id="emptyAdd">＋ ${esc(button)}</button>`:''}</div>`;}
function allRolls(){return state.filaments.flatMap(f=>(f.rolls||[]).map((r,i)=>({f,r,index:i})));}

function renderStats(){const all=allRolls(),rollCount=all.length,available=all.filter(x=>n(x.r.remainingG)>0).length,initial=all.reduce((a,x)=>a+n(x.r.initialG),0),remaining=all.reduce((a,x)=>a+n(x.r.remainingG),0),invested=all.reduce((a,x)=>a+n(x.r.price),0),remainingValue=all.reduce((a,x)=>a+(n(x.r.initialG)>0?n(x.r.price)*n(x.r.remainingG)/n(x.r.initialG):0),0);const cards=[['Filamentos',state.filaments.length,'Marcas y tipos registrados','◉'],['Rollos disponibles',`${available} / ${rollCount}`,'Unidades con material restante','▦'],['Material restante',grams(remaining),`${grams(initial-remaining)} consumidos`,'◉'],['Inversión',euro(invested),`${euro(remainingValue)} de valor restante aprox.`,'€']];$('stats').innerHTML=cards.map(c=>`<div class="stat-card"><div class="stat-top"><span>${c[0]}</span><span class="stat-icon">${c[3]}</span></div><div class="stat-value">${c[1]}</div><div class="stat-foot">${c[2]}</div></div>`).join('');}
function getFiltered(){const q=$('search').value.trim().toLocaleLowerCase(),mat=$('filterMaterial').value,brand=$('filterBrand').value,color=$('filterColor')?.value||'',stock=$('filterStock')?.value||'',availability=$('filterState').value;return state.filaments.filter(f=>{const t=totals(f),text=`${f.brand} ${f.name} ${f.material} ${f.colorName}`.toLocaleLowerCase();return(!q||text.includes(q))&&(!mat||f.material===mat)&&(!brand||f.brand===brand)&&(!color||f.colorName===color)&&(!availability||(availability==='available'?t.remaining>0:t.remaining<=0))&&(!stock||(stock==='low'?t.remaining>0&&t.remaining<=1000:stock==='medium'?t.remaining>1000&&t.remaining<=5000:t.remaining>5000));});}
function refreshFilters(){const old={mat:$('filterMaterial').value,brand:$('filterBrand').value,color:$('filterColor')?.value||''};const uniq=key=>[...new Set(state.filaments.map(f=>f[key]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,window.FilamentI18n?.language()||'es'));$('filterMaterial').innerHTML='<option value="">Todos los materiales</option>'+uniq('material').map(x=>`<option>${esc(x)}</option>`).join('');$('filterBrand').innerHTML='<option value="">Todas las marcas</option>'+uniq('brand').map(x=>`<option>${esc(x)}</option>`).join('');const fc=$('filterColor');fc.innerHTML='<option value="">Todos los colores</option>'+uniq('colorName').map(x=>`<option>${esc(x)}</option>`).join('');$('filterMaterial').value=old.mat;$('filterBrand').value=old.brand;fc.value=old.color;}
function safeImage(f){return typeof f.imageData==='string'&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=\s]+$/i.test(f.imageData)?f.imageData:'';}
function safeLink(url){try{const u=new URL(url,location.href);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function productImage(f,count,empty=false,cls='reel'){const photo=safeImage(f);if(photo)return `<span class="photo-reel ${cls}${empty?' is-empty':''}"><img src="${photo}" alt="Foto de ${esc(f.brand||'filamento')}"><b>${Math.max(1,count)}</b>${empty?'<i>×</i>':''}</span>`;return reel(f.colorHex,empty,cls,count,finishVisual(f));}
function renderList(){const items=getFiltered(),el=$('listView');if(!state.filaments.length){el.innerHTML=emptyState('Aún no hay filamentos','Añade el primer filamento para comenzar el inventario.','Añadir filamento');return;}if(!items.length){el.innerHTML=emptyState('No hay resultados','Prueba con otra búsqueda o cambia los filtros.');return;}el.innerHTML=items.map(f=>{const t=totals(f),available=t.remaining>0;return `<article class="filament-row" data-filament="${f.id}"><div>${productImage(f,t.rolls,!available,'row-art')}</div><div class="row-main"><strong><span data-no-i18n>${esc([f.brand,f.name].filter(Boolean).join(' ')||f.material)}</span></strong><small><span data-no-i18n>${esc(f.colorName||window.FilamentI18n?.t('Color sin nombre')||'Color sin nombre')}</span> · <span data-no-i18n>${esc(f.material)}</span> · ${finishMarkup(f)}</small></div><div class="row-sub"><div class="qty-control"><button type="button" data-qty="minus" data-id="${f.id}" aria-label="Quitar un rollo">−</button><b>${t.rolls} ${t.rolls===1?'rollo':'rollos'}</b><button type="button" data-qty="plus" data-id="${f.id}" aria-label="Añadir un rollo">＋</button></div><div>${grams(t.remaining)} / ${grams(t.initial)}</div></div><div class="row-sub hide-tablet"><span class="state-pill ${available?'':'empty'}">● ${available?'Disponible':'Agotado'}</span><div class="stock-meter"><span style="width:${t.percent}%"></span></div></div><div class="row-sub hide-tablet"><b>${fmtNumber(t.percent,1)} %</b><div>${grams(t.spent)} consumidos</div></div><div class="row-arrow">›</div></article>`}).join('');el.querySelectorAll('[data-filament]').forEach(x=>x.onclick=()=>openDetail(x.dataset.filament));el.querySelectorAll('[data-qty]').forEach(b=>b.onclick=e=>{e.stopPropagation();adjustRollCount(b.dataset.id,b.dataset.qty)});}
function renderGrid(){const el=$('gridView');el.innerHTML=`<div class="grid-toolbar"><div class="grid-control"><button id="colsMinus" aria-label="Menos columnas">−</button><input id="colsRange" type="range" min="2" max="15" value="${state.columns}"><button id="colsPlus" aria-label="Más columnas">＋</button><output>${state.columns} columnas</output></div><label class="check-label"><input id="hideEmpty" type="checkbox" ${state.hideEmpty?'checked':''}> Ocultar agotados</label></div><div class="spool-grid" id="spoolGrid" style="grid-template-columns:repeat(${state.columns},minmax(0,1fr))"></div>`;const setCols=v=>{state.columns=Math.max(2,Math.min(15,Number(v)||2));renderGrid();saveState();};$('colsRange').oninput=e=>{state.columns=Number(e.target.value);$('spoolGrid').style.gridTemplateColumns=`repeat(${state.columns},minmax(0,1fr))`;e.target.nextElementSibling.nextElementSibling.value=`${state.columns} columnas`;};$('colsRange').onchange=()=>saveState();$('colsMinus').onclick=()=>setCols(state.columns-1);$('colsPlus').onclick=()=>setCols(state.columns+1);$('hideEmpty').onchange=e=>{state.hideEmpty=e.target.checked;saveState();renderGrid();};let items=getFiltered();if(state.hideEmpty)items=items.filter(f=>totals(f).remaining>0);const grid=$('spoolGrid');if(!items.length){grid.innerHTML=emptyState(state.filaments.length?'No hay bobinas para mostrar':'Aún no hay filamentos','Añade un rollo o cambia los filtros.',state.filaments.length?'':'Añadir filamento');return;}grid.innerHTML=items.map(f=>{const t=totals(f);return `<article class="spool-card ${t.remaining<=0?'spent':''}" data-filament="${f.id}">${productImage(f,t.rolls,t.remaining<=0,'reel')}<strong><span data-no-i18n>${esc(f.brand||f.name||f.material)} · ${esc(f.name||'')}</span></strong><small><span data-no-i18n>${esc(f.material)}</span> · <span data-no-i18n>${esc(f.colorName||window.FilamentI18n?.t('Sin color')||'Sin color')}</span> · ${finishMarkup(f)}</small><div class="spool-weight">${t.rolls} ${t.rolls===1?'rollo':'rollos'} · ${grams(t.remaining)}</div></article>`}).join('');grid.querySelectorAll('[data-filament]').forEach(x=>x.onclick=()=>openDetail(x.dataset.filament));}
function render(){renderStats();refreshFilters();const isGrid=state.view==='grid';$('listView').classList.toggle('hidden',isGrid);$('gridView').classList.toggle('hidden',!isGrid);document.querySelectorAll('.view-tab').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));if(isGrid)renderGrid();else renderList();}

function newRoll(){return{id:uid(),initialG:1000,remainingG:1000,price:0,date:'',supplier:'',supplierUrl:''};}
function finishLabel(id,custom=''){if(custom.trim())return custom.trim();const label=({normal:'Normal',metallic:'Metálico',glossy:'Brillante',matte:'Mate',transparent:'Transparente',multicolor:'Multicolor'})[id]||'Normal';return window.FilamentI18n?.t(label)||label;}
function finishVisual(f){return f.customFinishName?(f.customFinishEffect||f.finish||'normal'):(f.finish||'normal');}
function finishMarkup(f){return f.customFinishName?.trim()?`<span data-no-i18n>${esc(f.customFinishName.trim())}</span>`:esc(finishLabel(f.finish,''));}
function updateFormPreview(){const root=$('formPreview');if(!root)return;root.innerHTML=reel($('colorHex').value,false,'preview-reel',1,$('customFinishName').value.trim()?$('customFinishEffect').value:$('finish').value);}
async function adjustRollCount(fid,action){const f=state.filaments.find(x=>x.id===fid);if(!f)return;f.rolls=Array.isArray(f.rolls)?f.rolls:[];if(action==='plus'){const previous=f.rolls.at(-1);$('bulkAddDialog').dataset.fid=fid;$('bulkCount').value='1';$('bulkDate').value=new Date().toISOString().slice(0,10);$('bulkWeight').value=Math.max(1,n(previous?.initialG)||1000);$('bulkPrice').value=Math.max(0,n(previous?.price));$('bulkSupplier').value=previous?.supplier||'';$('bulkUrl').value=previous?.supplierUrl||'';$('bulkAddDialog').showModal();return;}const actionChoice=prompt('¿Qué quieres hacer?\n1 = Retirar una bobina del inventario\n2 = Registrar consumo de una bobina','1');if(actionChoice===null)return;if(!['1','2'].includes(actionChoice)){showToast('Elige 1 para retirar o 2 para consumir.');return;}if(actionChoice==='1'&&f.rolls.length<=1){showToast('No puedes retirar la última bobina. Registra consumo o elimina el filamento desde su ficha.');return;}const options=f.rolls.map((r,i)=>`${i+1}: ${r.date||'sin fecha'} · ${grams(r.remainingG)} restantes · ${euro(r.price)} · ${r.supplier||'sin proveedor'}`).join('\n');const pick=prompt(`Escribe el número de la bobina:\n${options}`,String(f.rolls.length));if(pick===null)return;const index=Number(pick)-1;if(!Number.isInteger(index)||index<0||index>=f.rolls.length){showToast('Número de bobina no válido.');return;}const r=f.rolls[index];if(actionChoice==='1'){if(!confirm(`¿Retirar la bobina ${index+1}? Se eliminarán solo sus datos individuales.`))return;f.rolls.splice(index,1);await saveState();render();showToast('Bobina retirada.');return;}const answer=prompt(`¿Cuántos gramos consumiste de la bobina ${index+1}?`,'100');if(answer===null)return;const amount=Number(answer);if(!Number.isFinite(amount)||amount<=0||amount>n(r.remainingG)){showToast('Introduce un consumo válido que no supere el peso restante.');return;}r.remainingG=Math.max(0,n(r.remainingG)-amount);await saveState();render();showToast(`Consumo de ${grams(amount)} registrado en la bobina ${index+1}.`);}
function renderRollEditor(){const root=$('rollEditor');root.innerHTML=editingRolls.map((r,i)=>`<div class="roll-edit" data-roll-edit="${r.id}"><label>Rollo ${i+1}<input data-key="initialG" type="number" min="0" step="1" value="${n(r.initialG)}" title="Peso inicial en gramos"></label><label>Restante (g)<input data-key="remainingG" type="number" min="0" step="1" max="${n(r.initialG)}" value="${n(r.remainingG)}"></label><label>Precio (€)<input data-key="price" type="number" min="0" step="0.01" value="${n(r.price)}"></label><label>Compra<input data-key="date" type="date" value="${esc(r.date||'')}"></label><label>Proveedor<input data-key="supplier" list="supplierOptions" value="${esc(r.supplier||'')}" placeholder="Opcional"></label><label>Enlace<input data-key="supplierUrl" type="url" value="${esc(r.supplierUrl||'')}" placeholder="https://…"></label><button type="button" class="remove-roll" data-remove-roll="${r.id}" title="Eliminar rollo">×</button></div>`).join('');root.querySelectorAll('.roll-edit input').forEach(input=>input.onchange=()=>{const r=editingRolls.find(x=>x.id===input.closest('.roll-edit').dataset.rollEdit);r[input.dataset.key]=['date','supplier','supplierUrl'].includes(input.dataset.key)?input.value:n(input.value);if(input.dataset.key==='initialG'&&r.remainingG>r.initialG)r.remainingG=r.initialG;if(input.dataset.key==='supplier'){const found=state.suppliers.find(x=>norm(x.name)===norm(input.value));if(found&&found.url)r.supplierUrl=found.url;}});root.querySelectorAll('[data-remove-roll]').forEach(btn=>btn.onclick=()=>{if(editingRolls.length===1){showToast('Un filamento debe tener al menos un rollo.');return;}if(confirm('¿Eliminar este rollo del inventario?')){editingRolls=editingRolls.filter(r=>r.id!==btn.dataset.removeRoll);renderRollEditor();}});}
function renderPalette(){const root=$('palette'),colors=[...PRESET_COLORS,...(state.palette||[]).filter(c=>!PRESET_COLORS.includes(c))];root.innerHTML=colors.map(c=>`<button type="button" class="palette-swatch ${state.palette.includes(c)?'favorite':''}" title="${esc(COLOR_LABELS[c]||c)} · ${esc(c)}${state.palette.includes(c)?' · favorito':''}" aria-label="Usar color ${esc(COLOR_LABELS[c]||c)}" style="background:${esc(c)}" data-palette="${esc(c)}"></button>`).join('');root.querySelectorAll('[data-palette]').forEach(b=>b.onclick=()=>{setColor(b.dataset.palette);if(COLOR_LABELS[b.dataset.palette])$('colorName').value=COLOR_LABELS[b.dataset.palette];if(b.dataset.palette==='#B5E5F2')$('finish').value='transparent';updateFormPreview();});}
function resetForm(f=null){$('filamentForm').reset();currentPhoto=f?.imageData||null;showPhotoPreview(currentPhoto);$('filamentId').value=f?.id||'';$('formTitle').textContent=f?'Editar filamento':'Añadir filamento';$('brand').value=f?.brand||'';$('name').value=f?.name||'';$('material').value=f?.material||'PLA';$('colorName').value=f?.colorName||'';$('finish').value=f?.finish||'normal';$('customFinishName').value=f?.customFinishName||'';$('customFinishEffect').value=f?.customFinishEffect||'normal';$('colorHex').value=f?.colorHex||'#3478D4';$('colorText').value=($('colorHex').value).toUpperCase();$('nozzleMin').value=f?.nozzleMin??'';$('nozzleMax').value=f?.nozzleMax??'';$('bedMin').value=f?.bedMin??'';$('bedMax').value=f?.bedMax??'';editingRolls=JSON.parse(JSON.stringify(f?.rolls?.length?f.rolls:[newRoll()]));refreshTemplateSelect();initCatalogs();syncHslFromHex($('colorHex').value);$('ocrStatus').textContent='El texto reconocido se podrá revisar antes de guardar.';renderRollEditor();renderPalette();updateFormPreview();}
function openForm(f=null){resetForm(f);$('filamentDialog').showModal();}
function formData(){return{imageData:currentPhoto||null,brand:$('brand').value.trim(),name:$('name').value.trim(),material:$('material').value,colorName:$('colorName').value.trim(),finish:$('finish').value,customFinishName:$('customFinishName').value.trim(),customFinishEffect:$('customFinishEffect').value,colorHex:$('colorHex').value.toUpperCase(),nozzleMin:$('nozzleMin').value===''?null:n($('nozzleMin').value),nozzleMax:$('nozzleMax').value===''?null:n($('nozzleMax').value),bedMin:$('bedMin').value===''?null:n($('bedMin').value),bedMax:$('bedMax').value===''?null:n($('bedMax').value),rolls:editingRolls.map(r=>({...r,initialG:Math.max(0,n(r.initialG)),remainingG:Math.max(0,Math.min(n(r.initialG),n(r.remainingG))),price:Math.max(0,n(r.price))}))};}

function openDetail(id){currentDetailId=id;const f=state.filaments.find(x=>x.id===id);if(!f)return;const t=totals(f),matTemp=(lo,hi)=>lo==null&&hi==null?'—':`${lo??'—'}–${hi??'—'} °C`;const rows=(f.rolls||[]).map((r,i)=>`<div class="detail-roll"><div><strong>Rollo ${i+1}</strong><small><span>${window.FilamentI18n?.t('Inicial')||'Inicial'} ${grams(r.initialG)}</span> · <span>${window.FilamentI18n?.t('Usado')||'Usado'} ${grams(n(r.initialG)-n(r.remainingG))}</span> · <span>${fmtNumber(pct(r.remainingG,r.initialG),1)} % ${window.FilamentI18n?.t('disponible')||'disponible'}</span> · ${euro(r.price)} · <span data-no-i18n>${esc(r.date||(window.FilamentI18n?.t('Fecha sin registrar')||'Fecha sin registrar'))}</span> · <span data-no-i18n>${esc(r.supplier||window.FilamentI18n?.t('Sin proveedor')||'Sin proveedor')}</span></small></div><span class="roll-remain">${grams(r.remainingG)}</span>${safeLink(r.supplierUrl)?`<a href="${esc(safeLink(r.supplierUrl))}" target="_blank" rel="noopener"><span data-no-i18n>${esc(r.supplier||window.FilamentI18n?.t('Proveedor')||'Proveedor')}</span></a>`:''}<button data-consume="${r.id}" data-filament="${f.id}">Registrar consumo</button></div>`).join('');$('detailContent').innerHTML=`<div class="detail-wrap"><div class="detail-header"><div><span class="eyebrow">FICHA DEL FILAMENTO</span></div><button class="close-button detail-close" data-close="detailDialog" aria-label="Cerrar">×</button></div><div class="detail-hero">${productImage(f,t.rolls,t.remaining<=0,'reel')}<div><h2><span data-no-i18n>${esc([f.brand,f.name].filter(Boolean).join(' ')||f.material)}</span></h2><p><span data-no-i18n>${esc(f.material)}</span> · <span data-no-i18n>${esc(f.colorName||window.FilamentI18n?.t('Color sin nombre')||'Color sin nombre')}</span></p><div class="detail-tags"><span class="detail-tag">${esc(f.colorHex)}</span><span class="detail-tag">${finishMarkup(f)}</span><span class="detail-tag">${window.FilamentI18n?.t('Extrusor')||'Extrusor'} ${matTemp(f.nozzleMin,f.nozzleMax)}</span><span class="detail-tag">${window.FilamentI18n?.t('Cama')||'Cama'} ${matTemp(f.bedMin,f.bedMax)}</span></div><div class="detail-amount">${grams(t.remaining)} restantes</div><div class="detail-progress"><span style="width:${t.percent}%"></span></div><small class="muted">${fmtNumber(t.percent,1)} % disponible · ${grams(t.spent)} consumidos</small></div></div><div class="detail-facts"><div class="fact"><small>Comprado</small><strong>${grams(t.initial)}</strong></div><div class="fact"><small>Rollos</small><strong>${t.rolls} (${t.available} disponibles)</strong></div><div class="fact"><small>Invertido</small><strong>${euro(t.invested)}</strong></div><div class="fact"><small>Valor restante aprox.</small><strong>${euro(t.remainingValue)}</strong></div><div class="fact"><small>Material</small><strong><span data-no-i18n>${esc(f.material)}</span></strong></div><div class="fact"><small>Color</small><strong><i style="display:inline-block;width:11px;height:11px;border-radius:50%;background:${esc(f.colorHex)};vertical-align:-1px"></i> <span data-no-i18n>${esc(f.colorName||f.colorHex)}</span></strong></div></div><h3>Rollos individuales</h3><div class="detail-rolls">${rows}</div><div class="detail-actions"><button class="secondary-button" id="detailDelete">Eliminar filamento</button><button class="secondary-button" id="detailTemplate">Guardar como plantilla</button><button class="secondary-button" id="detailEdit">Editar datos</button></div></div>`;if(!$('detailDialog').open)$('detailDialog').showModal();$('detailContent').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('detailEdit').onclick=()=>{$('detailDialog').close();openForm(f);};$('detailTemplate').onclick=()=>saveTemplateFrom(f);$('detailDelete').onclick=async()=>{if(confirm('¿Eliminar el filamento y todos sus rollos? Esta acción no se puede deshacer.')){state.filaments=state.filaments.filter(x=>x.id!==f.id);await saveState();$('detailDialog').close();render();showToast('Filamento eliminado.');}};$('detailContent').querySelectorAll('[data-consume]').forEach(b=>b.onclick=()=>consume(b.dataset.filament,b.dataset.consume));}
async function consume(fid,rid){const f=state.filaments.find(x=>x.id===fid),r=f?.rolls.find(x=>x.id===rid);if(!r)return;const answer=prompt(`¿Cuántos gramos consumiste de Rollo ${f.rolls.indexOf(r)+1}?`, '100');if(answer===null)return;const amount=Number(answer);if(!Number.isFinite(amount)||amount<=0){showToast('Introduce una cantidad válida mayor que cero.');return;}if(amount>n(r.remainingG)){showToast('El consumo supera el peso restante.');return;}r.remainingG=Math.max(0,n(r.remainingG)-amount);await saveState();render();openDetail(fid);showToast(`Consumo de ${grams(amount)} registrado.`);}

async function exportBackup(){const payload={app:'Inventario Filamentos 3D',schemaVersion:2,exportedAt:new Date().toISOString(),data:{filaments:state.filaments,columns:state.columns,hideEmpty:state.hideEmpty,view:state.view,palette:state.palette,catalogs:state.catalogs,templates:state.templates,suppliers:state.suppliers}};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`inventario-filamentos-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);showToast('Copia JSON descargada.');}
function validateBackup(x){if(!x||x.app!=='Inventario Filamentos 3D'||![1,2].includes(x.schemaVersion)||!x.data||!Array.isArray(x.data.filaments))throw new Error('El archivo no tiene el formato esperado.');for(const f of x.data.filaments){if(!f.id||typeof f.material!=='string'||!Array.isArray(f.rolls))throw new Error('Hay un filamento con datos incompletos.');if(f.imageData&&!/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=\s]+$/i.test(f.imageData))throw new Error('Hay una fotografía con formato no compatible.');for(const r of f.rolls){if(!r.id||!Number.isFinite(Number(r.initialG))||!Number.isFinite(Number(r.remainingG))||!Number.isFinite(Number(r.price)))throw new Error('Hay un rollo con cantidades o precio no válidos.');}}return true;}
async function importBackup(file){try{const text=await file.text(),data=JSON.parse(text);validateBackup(data);if(!confirm(`La copia contiene ${data.data.filaments.length} filamentos. Importar reemplazará el inventario actual. ¿Continuar?`))return;state.filaments=mergeDuplicateFilaments(data.data.filaments);state.catalogs=data.data.catalogs||{brands:[],materials:[],names:[],colors:[]};state.templates=Array.isArray(data.data.templates)?data.data.templates:[];state.suppliers=Array.isArray(data.data.suppliers)?data.data.suppliers:[];state.columns=Math.max(2,Math.min(15,Number(data.data.columns)||5));state.hideEmpty=!!data.data.hideEmpty;state.view=['list','grid'].includes(data.data.view)?data.data.view:'list';state.palette=Array.isArray(data.data.palette)?data.data.palette:[];initCatalogs();await saveState();$('backupDialog').close();render();showToast('Copia restaurada correctamente.');}catch(e){void window.FilamentDiagnostics?.log('Importación JSON',e);alert(`No se pudo importar la copia: ${e.message}`);}}

let ocrWorker=null,ocrPromise=null;
async function getOcrWorker(){if(ocrWorker)return ocrWorker;if(!window.Tesseract)throw new Error('El motor OCR local no está disponible.');if(!ocrPromise)ocrPromise=window.Tesseract.createWorker('eng',1,{workerPath:'./assets/worker.min.js',corePath:'./assets',langPath:'./assets/tessdata',gzip:false,logger:m=>{if(m.status==='recognizing text')$('ocrStatus').textContent=`Leyendo etiqueta… ${Math.round((m.progress||0)*100)} %`;}});ocrWorker=await ocrPromise;return ocrWorker;}
async function runOcr(file){
  if(!file)return;
  $('ocrStatus').textContent='Preparando OCR local…';
  try{
    const worker=await getOcrWorker(),result=await worker.recognize(file),text=result.data.text||'';
    if(!text.trim()){$('ocrStatus').textContent='No se reconoció texto. Completa los datos manualmente.';return;}
    const lines=text.split(/\n+/).map(x=>x.trim()).filter(Boolean),joined=lines.join(' ');
    const materials=['PLA+','PLA','PETG','ABS','ASA','TPU','PA','PC'];
    const escapeRe=x=>x.replace(/[.*+?^$()|[\]\\]/g,'\\$&');
    const matchesToken=(source,token)=>new RegExp('(?:^|[^A-Z0-9])'+escapeRe(token)+'(?![A-Z0-9])','i').test(source);
    const material=materials.find(m=>matchesToken(joined,m));
    const hex=joined.match(/#[0-9A-F]{6}\b/i);
    const brandList=['eSUN','Bambu Lab','Prusament','Polymaker','SUNLU','OVERTURE','Hatchbox','Creality'];
    const brand=brandList.find(b=>joined.toLowerCase().includes(b.toLowerCase()));
    const weight=joined.match(/(\d+(?:[.,]\d+)?)\s*(kg|g)\b/i);
    const colors=['black','white','red','blue','green','yellow','orange','silver','grey','gray','brown','purple','pink','negro','blanco','rojo','azul','verde','amarillo','naranja','plata','gris','marrón','morado'];
    const color=colors.find(c=>matchesToken(joined,c));
    const tempRange=label=>{const re=new RegExp(label+'[^0-9]{0,28}(\\d{2,3})\\s*(?:°?C)?\\s*[-–~]\\s*(\\d{2,3})','i'),m=joined.match(re);return m?[Number(m[1]),Number(m[2])]:null;};
    const nozzle=tempRange('(?:nozzle|extruder|hotend|extrusor)'),bed=tempRange('(?:bed|platform|cama)');
    if(brand&&!$('brand').value)$('brand').value=brand;
    if(material)$('material').value=material;
    if(!$('name').value&&material){
      const candidate=lines.find(line=>matchesToken(line,material)&&line.length<55);
      if(candidate){const cleaned=brand?candidate.replace(new RegExp(escapeRe(brand),'i'),'').trim():candidate;$('name').value=cleaned||material;}
    }
    if(color&&!$('colorName').value)$('colorName').value=color.charAt(0).toUpperCase()+color.slice(1);
    if(hex){$('colorHex').value=hex[0];$('colorText').value=hex[0].toUpperCase();updateFormPreview();}
    if(nozzle){$('nozzleMin').value=nozzle[0];$('nozzleMax').value=nozzle[1];}
    if(bed){$('bedMin').value=bed[0];$('bedMax').value=bed[1];}
    if(weight){const gramsValue=Number(weight[1].replace(',','.'))*(weight[2].toLowerCase()==='kg'?1000:1);editingRolls[0].initialG=gramsValue;editingRolls[0].remainingG=gramsValue;renderRollEditor();}
    $('ocrStatus').textContent='Texto leído localmente. Revisa y confirma: '+lines.slice(0,5).join(' · ');
  }catch(e){void window.FilamentDiagnostics?.log('OCR local',e);$('ocrStatus').textContent='No se pudo completar el OCR ('+e.message+'). Puedes registrar el filamento manualmente.';}
}

function bind(){ $('addBtn').onclick=()=>openForm();$('addRollBtn').onclick=()=>{editingRolls.push(newRoll());renderRollEditor();};$('bulkAddForm').onsubmit=async e=>{e.preventDefault();const fid=$('bulkAddDialog').dataset.fid,f=state.filaments.find(x=>x.id===fid),count=Math.max(1,Math.min(99,Number($('bulkCount').value)||1)),weight=Math.max(1,n($('bulkWeight').value)),price=Math.max(0,n($('bulkPrice').value)),date=$('bulkDate').value,supplier=$('bulkSupplier').value.trim(),supplierUrl=$('bulkUrl').value.trim();if(!f)return;for(let i=0;i<count;i++)f.rolls.push({id:uid(),initialG:weight,remainingG:weight,price,date,supplier,supplierUrl});await saveState();$('bulkAddDialog').close();render();showToast(`${count} ${count===1?'bobina añadida':'bobinas añadidas'}.`);};$('bulkSupplier').onchange=()=>{const s=state.suppliers.find(x=>norm(x.name)===norm($('bulkSupplier').value));if(s?.url)$('bulkUrl').value=s.url;};$('saveColorBtn').onclick=async()=>{const c=$('colorHex').value.toUpperCase();if(!state.palette.some(x=>norm(x)===norm(c))){state.palette.push(c);await saveState();renderPalette();showToast('Color guardado en favoritos.');}else showToast('Ese color ya está en favoritos.');};$('filamentForm').onsubmit=async e=>{e.preventDefault();if($('filamentForm').dataset.saving==='yes')return;if(!editingRolls.length){showToast('Añade al menos un rollo.');return;}const data=formData();if(!data.brand&&!data.name){showToast('Añade una marca o nombre comercial.');return;}if(!data.material.trim()){showToast('Indica el material.');return;}if(data.nozzleMin!=null&&data.nozzleMax!=null&&data.nozzleMin>data.nozzleMax||data.bedMin!=null&&data.bedMax!=null&&data.bedMin>data.bedMax){showToast('Revisa los rangos de temperatura.');return;}$('filamentForm').dataset.saving='yes';const id=$('filamentId').value||uid(),idx=state.filaments.findIndex(f=>f.id===id);if(idx>=0)state.filaments[idx]={...state.filaments[idx],...data,id};else state.filaments.push({...data,id});state.filaments=mergeDuplicateFilaments(state.filaments);const addUnique=(arr,value)=>{if(value?.trim()&&!arr.some(x=>norm(x)===norm(value)))arr.push(value.trim());};addUnique(state.catalogs.brands,data.brand);addUnique(state.catalogs.materials,data.material);addUnique(state.catalogs.names,data.name);addUnique(state.catalogs.colors,data.colorName);await saveState();$('filamentForm').dataset.saving='';initCatalogs();$('filamentDialog').close();render();showToast('Filamento guardado.');};$('colorHex').oninput=e=>setColor(e.target.value);$('colorText').onchange=e=>{const val=e.target.value.trim();if(/^#[0-9a-f]{6}$/i.test(val))setColor(val);else e.target.value=$('colorHex').value.toUpperCase();};for(const id of ['hueRange','satRange','lightRange'])$(id).oninput=()=>setColor(hslHex(Number($('hueRange').value),Number($('satRange').value),Number($('lightRange').value)));$('brand').oninput=()=>refreshNameOptions($('brand').value);$('finish').onchange=updateFormPreview;$('customFinishName').oninput=updateFormPreview;$('customFinishEffect').onchange=updateFormPreview;$('templateSelect').onchange=e=>applyTemplate(e.target.value);$('photoFile').onchange=async e=>{const file=e.target.files[0];if(file){try{showPhotoPreview(await imageToDataUrl(file));showToast('Fotografía preparada y comprimida localmente.');}catch(err){void window.FilamentDiagnostics?.log('Fotografía',err);alert(err.message);}}e.target.value='';};$('removePhotoBtn').onclick=()=>showPhotoPreview(null);$('ocrFile').onchange=e=>runOcr(e.target.files[0]);$('search').oninput=()=>state.view==='grid'?renderGrid():renderList();['filterMaterial','filterBrand','filterColor','filterStock','filterState'].forEach(id=>$(id).onchange=()=>state.view==='grid'?renderGrid():renderList());document.querySelectorAll('.view-tab').forEach(b=>b.onclick=async()=>{state.view=b.dataset.view;await saveState();render();});$('backupBtn').onclick=()=>$('backupDialog').showModal();$('exportBtn').onclick=exportBackup;$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=e=>{if(e.target.files[0])importBackup(e.target.files[0]);e.target.value='';};$('templatesBtn').onclick=()=>openManager('templates');$('catalogsBtn').onclick=()=>openManager('catalogs');$('pdfBtn').onclick=printInventory;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.body.addEventListener('click',e=>{if(e.target.id==='emptyAdd')openForm();});}

async function init(){try{db=await openDb();const cloudUser=await window.FilamentCloud?.initialize(db);currentDbKey=cloudUser?.uid?'profile:'+cloudUser.uid:(cloudUser?.storageKey||'main');const stored=await loadState();if(stored){const before=Array.isArray(stored.filaments)?stored.filaments:[];state.filaments=mergeDuplicateFilaments(before);state.catalogs=stored.catalogs||{brands:[],materials:[],names:[],colors:[]};state.templates=Array.isArray(stored.templates)?stored.templates:[];state.suppliers=Array.isArray(stored.suppliers)?stored.suppliers:[];state.columns=Math.max(2,Math.min(15,Number(stored.columns)||5));state.hideEmpty=!!stored.hideEmpty;state.view=['list','grid'].includes(stored.view)?stored.view:'list';state.palette=Array.isArray(stored.palette)?stored.palette:[];if(state.filaments.length!==before.length||!stored.catalogs||!stored.templates||!stored.suppliers)await saveState();}}catch(e){console.error(e);void window.FilamentDiagnostics?.log('Almacenamiento local',e);alert('No se pudo abrir el almacenamiento local. Revisa la configuración del navegador.');}initCatalogs();bind();render();window.addEventListener('filaments-language-change',()=>{render();if($('filamentDialog')?.open)refreshTemplateSelect($('templateSelect').value);if($('detailDialog')?.open&&currentDetailId)openDetail(currentDetailId);if($('managerDialog')?.open&&currentManagerKind){$('managerDialog').close();openManager(currentManagerKind);}});if(window.FilamentCloud)window.FilamentCloud.attach(window.FilamentApp);if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(e=>{console.warn('SW:',e);void window.FilamentDiagnostics?.log('Service Worker',e);});}
init();

