function refreshNameOptions(brand=''){const brandNames={'bambu lab':['PLA Basic','PLA Matte','PLA Silk','PLA Tough','PETG Basic','PETG HF','PETG-CF','ABS','ASA','TPU 95A'],'esun':['PLA+','ePLA-HF','ePLA-Matte','ePLA-Silk','PETG','ABS+','TPU-95A'],'sunlu':['PLA+','PLA Meta','PLA Matte','PLA Silk','PETG','ABS','TPU'],'polymaker':['PolyLite PLA','PolyTerra PLA','PolyMax PLA','PolyLite PETG','PolyMax PETG','PolyFlex TPU'],'prusament':['Prusament PLA','Prusament PETG','Prusament ASA','Prusament PC Blend'],'elegoo':['PLA','PLA+','Rapid PETG','PETG Pro','ABS','TPU'],'creality':['Hyper PLA','Ender PLA','PETG','CR-TPU']};const related=brandNames[norm(brand)]||brandNames[norm(brand).replace(/\s/g,'')]||[];const all=[...new Set([...related,...DEFAULT_NAMES,...state.catalogs.names])];$('nameOptions').innerHTML=all.map(x=>`<option value="${esc(x)}">`).join('');}
function initCatalogs(){state.catalogs=state.catalogs||{};for(const k of ['brands','materials','names','colors'])if(!Array.isArray(state.catalogs[k]))state.catalogs[k]=[];state.suppliers=Array.isArray(state.suppliers)?state.suppliers:[];state.templates=Array.isArray(state.templates)?state.templates:[];const fill=(base,custom)=>[...new Map([...base,...custom].map(x=>[norm(typeof x==='string'?x:x.name),x])).values()];$('brandOptions').innerHTML=fill(DEFAULT_BRANDS,state.catalogs.brands).map(x=>`<option value="${esc(typeof x==='string'?x:x.name)}">`).join('');$('materialOptions').innerHTML=fill(DEFAULT_MATERIALS,state.catalogs.materials).map(x=>`<option value="${esc(typeof x==='string'?x:x.name)}">`).join('');refreshNameOptions($('brand')?.value||'');$('colorOptions').innerHTML=[...DEFAULT_COLORS.map(x=>x[1]),...state.catalogs.colors].map(x=>`<option value="${esc(x)}">`).join('');$('supplierOptions').innerHTML=state.suppliers.map(x=>`<option value="${esc(x.name)}">`).join('');}
function refreshTemplateSelect(selected=''){const el=$('templateSelect');if(!el)return;el.disabled=!!$('filamentId').value;el.title=el.disabled?'Las plantillas solo se aplican al crear filamentos nuevos':'';el.innerHTML='<option value="">Sin plantilla</option>'+state.templates.map(t=>`<option value="${t.id}">${esc(t.title||t.name)}${t.withoutColor?' · '+(window.FilamentI18n?.t('sin color')||'sin color'):''}</option>`).join('');el.value=selected;}
function templateData(f,withoutColor=false){const keys=['brand','name','material','colorName','finish','customFinishName','customFinishEffect','colorHex','nozzleMin','nozzleMax','bedMin','bedMax'];const d={};for(const k of keys)d[k]=f[k]??'';if(withoutColor){d.colorName='';d.colorHex='#3478D4';}d.productName=d.name;delete d.name;return{...d,preferredSupplier:f.rolls?.at(-1)?.supplier||'',withoutColor};}
async function saveTemplateFrom(f){const name=prompt('Nombre para la plantilla:',`${f.brand||''} ${f.name||f.material}`.trim());if(!name?.trim())return;const withoutColor=confirm('¿Guardar como plantilla sin color? Aceptar = sin color; Cancelar = plantilla completa.');const data=templateData(f,withoutColor);if(!confirm('¿Guardar también el proveedor habitual de la última bobina? Aceptar = guardar proveedor.'))data.preferredSupplier='';state.templates.push({id:uid(),title:name.trim(),...data});await saveState();showToast('Plantilla guardada.');}
function applyTemplate(id){const t=state.templates.find(x=>x.id===id);if(!t)return;for(const k of ['brand','material','colorName','finish','customFinishName','customFinishEffect','nozzleMin','nozzleMax','bedMin','bedMax'])if(t[k]!==undefined)$(k).value=t[k];$('name').value=t.productName??t.name??'';$('colorHex').value=/^#[0-9a-f]{6}$/i.test(t.colorHex)?t.colorHex:'#3478D4';$('colorText').value=$('colorHex').value.toUpperCase();if(t.preferredSupplier&&editingRolls[0]){editingRolls[0].supplier=t.preferredSupplier;const supplier=state.suppliers.find(x=>norm(x.name)===norm(t.preferredSupplier));if(supplier?.url)editingRolls[0].supplierUrl=supplier.url;}currentPhoto=null;renderRollEditor();renderPalette();syncHslFromHex($('colorHex').value);updateFormPreview();}
function openManager(kind){currentManagerKind=kind;const title=$('managerTitle'),root=$('managerContent');if(kind==='catalogs'){title.textContent='Marcas, materiales y proveedores';root.innerHTML=`<p class="muted">Las sugerencias se pueden quitar sin borrar registros existentes.</p><div class="manager-group"><h3>Marcas personalizadas</h3><div>${state.catalogs.brands.map((x,i)=>`<span class="manager-chip"><span data-no-i18n>${esc(x)}</span> <button data-editcat="brands" data-index="${i}">✎</button><button data-delcat="brands" data-index="${i}">×</button></span>`).join('')}</div><button class="secondary-button" data-addcat="brands">＋ Añadir marca</button></div><div class="manager-group"><h3>Materiales personalizados</h3><div>${state.catalogs.materials.map((x,i)=>`<span class="manager-chip"><span data-no-i18n>${esc(x)}</span> <button data-editcat="materials" data-index="${i}">✎</button><button data-delcat="materials" data-index="${i}">×</button></span>`).join('')}</div><button class="secondary-button" data-addcat="materials">＋ Añadir material</button></div><div class="manager-group"><h3>Nombres comerciales personalizados</h3><div>${state.catalogs.names.map((x,i)=>`<span class="manager-chip"><span data-no-i18n>${esc(x)}</span> <button data-editcat="names" data-index="${i}">✎</button><button data-delcat="names" data-index="${i}">×</button></span>`).join('')}</div><button class="secondary-button" data-addcat="names">＋ Añadir nombre</button></div><div class="manager-group"><h3>Proveedores</h3>${state.suppliers.map((x,i)=>`<div class="manager-provider"><span><b data-no-i18n>${esc(x.name)}</b> ${safeLink(x.url)?`· <a href="${esc(safeLink(x.url))}" target="_blank" rel="noopener">${esc(x.url)}</a>`:''}<small><span data-no-i18n>${esc(x.notes||'')}</span></small></span><button data-editsupplier="${i}">Editar</button><button data-delsupplier="${i}">Eliminar</button></div>`).join('')}<button class="secondary-button" data-addsupplier>＋ Añadir proveedor</button></div>`;root.querySelectorAll('[data-addcat]').forEach(b=>b.onclick=async()=>{const label={brands:'marca',materials:'material',names:'nombre comercial'}[b.dataset.addcat],v=prompt(`Nuevo ${label}:`);if(v?.trim()&&!state.catalogs[b.dataset.addcat].some(x=>norm(x)===norm(v)))state.catalogs[b.dataset.addcat].push(v.trim());await saveState();openManager('catalogs');initCatalogs();});root.querySelectorAll('[data-editcat]').forEach(b=>b.onclick=async()=>{const arr=state.catalogs[b.dataset.editcat],i=Number(b.dataset.index),old=arr[i],v=prompt('Editar sugerencia:',old);if(v?.trim()&&!arr.some((x,j)=>j!==i&&norm(x)===norm(v))){arr[i]=v.trim();await saveState();openManager('catalogs');initCatalogs();}});root.querySelectorAll('[data-delcat]').forEach(b=>b.onclick=async()=>{const arr=state.catalogs[b.dataset.delcat],v=arr[Number(b.dataset.index)];if(confirm(`¿Quitar «${v}» de las sugerencias? Los registros guardados no cambiarán.`)){arr.splice(Number(b.dataset.index),1);await saveState();openManager('catalogs');initCatalogs();}});root.querySelector('[data-addsupplier]')?.addEventListener('click',async()=>editSupplier());root.querySelectorAll('[data-editsupplier]').forEach(b=>b.onclick=()=>editSupplier(Number(b.dataset.editsupplier)));root.querySelectorAll('[data-delsupplier]').forEach(b=>b.onclick=async()=>{const i=Number(b.dataset.delsupplier);if(confirm('¿Eliminar este proveedor del catálogo? Las compras guardadas conservan su texto y enlace.')){state.suppliers.splice(i,1);await saveState();openManager('catalogs');initCatalogs();}});}else{title.textContent='Plantillas de filamento';root.innerHTML=`<p class="muted">Las plantillas crean nuevos registros y no alteran bobinas ya guardadas.</p><button class="secondary-button" id="newTemplate">＋ Crear plantilla manual</button><div class="manager-list">${state.templates.map((t,i)=>`<article><div><b data-no-i18n>${esc(t.title||t.name)}</b><small><span data-no-i18n>${esc(t.brand||'')}</span> · <span data-no-i18n>${esc(t.material||'')}</span> · ${t.withoutColor?(window.FilamentI18n?.t('sin color')||'sin color'):`<span data-no-i18n>${esc(t.colorName||'color')}</span>`}</small></div><button data-duptemplate="${i}">Duplicar</button><button data-edtemplate="${i}">Editar</button><button data-deltemplate="${i}">Eliminar</button></article>`).join('')||'<p class="muted">Todavía no hay plantillas.</p>'}</div>`;$('newTemplate').onclick=()=>createManualTemplate();root.querySelectorAll('[data-deltemplate]').forEach(b=>b.onclick=async()=>{const i=Number(b.dataset.deltemplate);if(confirm('¿Eliminar esta plantilla?')){state.templates.splice(i,1);await saveState();openManager('templates');}});root.querySelectorAll('[data-duptemplate]').forEach(b=>b.onclick=async()=>{const t=state.templates[Number(b.dataset.duptemplate)];state.templates.push({...t,id:uid(),title:`${t.title||t.name} (copia)`});await saveState();openManager('templates');});root.querySelectorAll('[data-edtemplate]').forEach(b=>b.onclick=async()=>{const i=Number(b.dataset.edtemplate),t=state.templates[i];const val=(label,key)=>prompt(`${label}:`,t[key]??'');const name=val('Nombre de plantilla','title');if(!name?.trim())return;const withoutColor=confirm('¿Debe ser una plantilla sin color? Aceptar = sin color.');const brand=val('Marca','brand'),commercial=val('Nombre comercial','productName'),material=val('Material','material'),colorName=withoutColor?'':val('Color','colorName'),hex=withoutColor?t.colorHex:val('Código hexadecimal (#RRGGBB)','colorHex'),finish=val('Acabado (normal, metallic, glossy, matte, transparent, multicolor)','finish'),customFinishName=val('Descripción del acabado','customFinishName'),customFinishEffect=val('Efecto visual','customFinishEffect'),preferredSupplier=val('Proveedor habitual (opcional)','preferredSupplier'),nozzleMin=val('Temperatura extrusor mínima','nozzleMin'),nozzleMax=val('Temperatura extrusor máxima','nozzleMax'),bedMin=val('Temperatura cama mínima','bedMin'),bedMax=val('Temperatura cama máxima','bedMax');state.templates[i]={...t,title:name.trim(),withoutColor,brand:brand??t.brand,productName:commercial??t.productName??t.name,material:material??t.material,colorName:withoutColor?'':(colorName??t.colorName),preferredSupplier:preferredSupplier??t.preferredSupplier,colorHex:/^#[0-9a-f]{6}$/i.test(hex||'')?hex:t.colorHex,finish:finish??t.finish,customFinishName:customFinishName??t.customFinishName,customFinishEffect:customFinishEffect??t.customFinishEffect,nozzleMin:nozzleMin===''?null:(nozzleMin??t.nozzleMin),nozzleMax:nozzleMax===''?null:(nozzleMax??t.nozzleMax),bedMin:bedMin===''?null:(bedMin??t.bedMin),bedMax:bedMax===''?null:(bedMax??t.bedMax)};await saveState();openManager('templates');});} if(!$('managerDialog').open)$('managerDialog').showModal();}
async function editSupplier(index=null){const old=index==null?{}:state.suppliers[index],name=prompt('Nombre del proveedor:',old.name||'');if(!name?.trim())return;const url=prompt('Página web o enlace del producto (opcional):',old.url||'')||'',notes=prompt('Notas opcionales:',old.notes||'')||'',item={name:name.trim(),url:url.trim(),notes:notes.trim()};if(index==null){if(state.suppliers.some(x=>norm(x.name)===norm(item.name))){showToast('Ese proveedor ya existe.');return;}state.suppliers.push(item);}else state.suppliers[index]=item;await saveState();initCatalogs();openManager('catalogs');}
async function createManualTemplate(){const title=prompt('Nombre de la plantilla:');if(!title?.trim())return;const brand=prompt('Marca (opcional):','')||'',productName=prompt('Nombre comercial (opcional):','')||'',material=prompt('Material:','PLA')||'PLA',withoutColor=confirm('¿Será una plantilla sin color? Aceptar = sin color.');const colorName=withoutColor?'':prompt('Nombre del color (opcional):','')||'',colorHex=withoutColor?'#3478D4':(prompt('Código hexadecimal (#RRGGBB):','#3478D4')||'#3478D4'),finish=prompt('Acabado: normal, metallic, glossy, matte, transparent o multicolor','normal')||'normal',customFinishName=prompt('Descripción del acabado (opcional):','')||'',customFinishEffect=prompt('Efecto visual: normal, metallic, glossy, matte, transparent o multicolor',finish)||finish,nozzleMin=prompt('Temperatura mínima del extrusor (opcional):','')||'',nozzleMax=prompt('Temperatura máxima del extrusor (opcional):','')||'',bedMin=prompt('Temperatura mínima de cama (opcional):','')||'',bedMax=prompt('Temperatura máxima de cama (opcional):','')||'';state.templates.push({id:uid(),title:title.trim(),brand,productName,material,colorName,colorHex:/^#[0-9a-f]{6}$/i.test(colorHex)?colorHex:'#3478D4',finish,customFinishName,customFinishEffect,withoutColor,nozzleMin:nozzleMin===''?null:n(nozzleMin),nozzleMax:nozzleMax===''?null:n(nozzleMax),bedMin:bedMin===''?null:n(bedMin),bedMax:bedMax===''?null:n(bedMax)});await saveState();openManager('templates');}
function hslHex(h,s,l){s/=100;l/=100;const k=n=>(n+h/30)%12,a=s*Math.min(l,1-l),f=n=>Math.round(255*(l-a*Math.max(-1,Math.min(k(n)-3,Math.min(9-k(n),1))))).toString(16).padStart(2,'0');return '#'+f(0)+f(8)+f(4);}
function hexHsl(hex){const n=parseInt(hex.slice(1),16),r=((n>>16)&255)/255,g=((n>>8)&255)/255,b=(n&255)/255,max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min,l=(max+min)/2;let h=0,s=0;if(d){s=d/(1-Math.abs(2*l-1));switch(max){case r:h=((g-b)/d)%6;break;case g:h=(b-r)/d+2;break;default:h=(r-g)/d+4;}h*=60;if(h<0)h+=360;}return[Math.round(h),Math.round(s*100),Math.round(l*100)];}
function syncHslFromHex(hex){if(!/^#[0-9a-f]{6}$/i.test(hex))return;const [h,s,l]=hexHsl(hex);$('hueRange').value=h;$('satRange').value=s;$('lightRange').value=l;}
function setColor(hex){if(!/^#[0-9a-f]{6}$/i.test(hex))return;$('colorHex').value=hex;$('colorText').value=hex.toUpperCase();syncHslFromHex(hex);updateFormPreview();}
function imageToDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('No se pudo leer la fotografía.'));reader.onload=()=>{const img=new Image();img.onload=()=>{const scale=Math.min(1,900/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.78));};img.onerror=()=>reject(new Error('Formato de imagen no compatible.'));img.src=reader.result;};reader.readAsDataURL(file);});}
function showPhotoPreview(data){currentPhoto=data||null;const img=$('photoPreview');img.classList.toggle('hidden',!data);$('photoHint').classList.toggle('hidden',!!data);$('removePhotoBtn').classList.toggle('hidden',!data);if(data)img.src=data;}
function printInventory(){const filaments=state.filaments,all=allRolls(),brands=[...new Set(filaments.map(f=>f.brand||(window.FilamentI18n?.t('Sin marca')||'Sin marca')))].sort((a,b)=>a.localeCompare(b,window.FilamentI18n?.language()||'es')),initial=all.reduce((s,x)=>s+n(x.r.initialG),0),remaining=all.reduce((s,x)=>s+n(x.r.remainingG),0),value=all.reduce((s,x)=>s+(n(x.r.initialG)>0?n(x.r.price)*n(x.r.remainingG)/n(x.r.initialG):0),0),materials=[...new Set(filaments.map(f=>f.material))].sort().join(', ');let html=`<header class="print-header"><h1>Inventario Filamentos 3D</h1><p>Generado: ${new Date().toLocaleString(locale())}</p><div class="print-summary"><span><b>${filaments.length}</b> referencias</span><span><b>${all.length}</b> bobinas</span><span><b>${grams(remaining)}</b> disponibles / ${grams(initial)} iniciales</span><span><b>${euro(value)}</b> valor restante aprox.</span><span><b>Materiales:</b> <span data-no-i18n>${esc(materials||'—')}</span></span><span><b>Marcas:</b> ${esc(brands.join(', ')||'—')}</span></div></header>`;for(const brand of brands){html+=`<section class="print-brand"><h2><span data-no-i18n>${esc(brand)}</span></h2><div class="print-grid">`;for(const f of filaments.filter(x=>(x.brand||(window.FilamentI18n?.t('Sin marca')||'Sin marca'))===brand)){const t=totals(f),pic=f.imageData?`<img src="${f.imageData}" alt="">`:reel(f.colorHex,t.remaining<=0,'print-reel',t.rolls,finishVisual(f));html+=`<article class="print-card"><div class="print-product">${pic}<div><h3><span data-no-i18n>${esc(f.name||f.material)}</span></h3><p><span data-no-i18n>${esc(f.material)}</span> · <span data-no-i18n>${esc(f.colorName||window.FilamentI18n?.t('Sin color')||'Sin color')}</span> · ${finishMarkup(f)}</p><p><b>${t.rolls} ${t.rolls===1?'bobina':'bobinas'}</b> · ${grams(t.remaining)} restantes</p><p>Precio invertido: ${euro(t.invested)} · Proveedor/es: <span data-no-i18n>${esc([...new Set(f.rolls.map(r=>r.supplier).filter(Boolean))].join(', ')||'—')}</span></p></div></div><table><thead><tr><th>Rollo</th><th>Compra</th><th>Inicial</th><th>Restante</th><th>Precio</th><th>Proveedor</th></tr></thead><tbody>${f.rolls.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.date||'—')}</td><td>${grams(r.initialG)}</td><td>${grams(r.remainingG)}</td><td>${euro(r.price)}</td><td><span data-no-i18n>${esc(r.supplier||'—')}</span></td></tr>`).join('')}</tbody></table></article>`;}html+='</div></section>';}$('printArea').innerHTML=html;window.FilamentI18n?.translateTree($('printArea'));window.print();}
